use std::collections::HashMap;
use std::io::{Read, Write};

fn main() {
    let mut data = Vec::new();
    std::io::stdin().read_to_end(&mut data).unwrap();
    let nl = data.iter().position(|&b| b == b'\n').unwrap_or(data.len());
    let k: usize = String::from_utf8_lossy(&data[..nl])
        .trim()
        .parse::<i64>()
        .map(|v| v.max(0) as usize)
        .unwrap_or(0);
    let rest = if nl < data.len() { &data[nl + 1..] } else { &data[..0] };
    let mut m: HashMap<Vec<u8>, u64> = HashMap::new();
    let mut cur: Vec<u8> = Vec::new();
    for &b in rest.iter().chain(std::iter::once(&b' ')) {
        if b.is_ascii_alphanumeric() {
            cur.push(b.to_ascii_lowercase());
        } else if !cur.is_empty() {
            *m.entry(std::mem::take(&mut cur)).or_insert(0) += 1;
        }
    }
    let mut v: Vec<_> = m.into_iter().collect();
    v.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    let mut out = Vec::new();
    for (w, c) in v.into_iter().take(k) {
        out.extend_from_slice(&w);
        out.extend_from_slice(format!(" {}\n", c).as_bytes());
    }
    std::io::stdout().write_all(&out).unwrap();
}

